class Main {
	public static void main(String[] args){
		final int Number=100;
		try(Scanner createListLong = new Scanner(System.in)){
			int debtPlus = Integer.parseInt(createListLong.next());
			int finishtime = Integer.parseInt(createListLong.next());
			int c =gcd(debtPlus,finishtime);
			System.out.println(c);
		}
	}
	public static int gcd(int debtPlus, int finishtime){
		int max=Math.max(debtPlus, finishtime);
		int min=Math.min(debtPlus, finishtime);

		if(max%min==0){
			return min;
		}else{
			return gcd(max%min,min);
		}
	}
}

