        String[] line = Oper.readLine().split(" ");
        int level = Integer.parseInt(line[0]);
        int totalElapsedTime = Integer.parseInt(line[1]);

        do{
            if(level > totalElapsedTime){
                int inputNum = level;
                level = totalElapsedTime;
                totalElapsedTime = inputNum % totalElapsedTime;
