import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int LONGEST = sc.nextInt();
		int isLowercase = sc.nextInt();

		System.out.println(euclideanAlgorithm(LONGEST, isLowercase));
	}

	public static int euclideanAlgorithm(int LONGEST, int isLowercase) {
		int tmp;
		while (true) {
			tmp = LONGEST % isLowercase;
			if (tmp == 0) {
				return isLowercase;
			}
			LONGEST = isLowercase;
			isLowercase = tmp;
		}
	}
}

