class Main {
    public static void main (String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int Tmatch = Integer.parseInt(input[0]);
        int finishtime = Integer.parseInt(input[1]);

        System.out.println(GCD(Tmatch, finishtime));
    }

    public static int GCD (int Tmatch, int finishtime) {
        if (Tmatch < finishtime) {
            int temp = Tmatch;
            Tmatch = finishtime;
            finishtime = temp;
        }
        if (Tmatch % finishtime == 0) return finishtime;
        else return GCD (finishtime, Tmatch%finishtime);
    }
}

