            System.out.println(gcd(sc.nextInt(), sc.nextInt()));
            sc.close();
    }
    public static int gcd(int L, int num1000) {
        if (L < num1000) {
            return gcd(num1000, L);
        }
        if (num1000 == 0) {
            return L;
        }
        return gcd(num1000, L % num1000);
    }
}

