import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String Task = scan.next();
        String time_cost = scan.next();

        int x = Integer.parseInt(Task);
        int y = Integer.parseInt(time_cost);

        int answer = divisor(x, y);

        System.out.println(answer);
        scan.close();
    }

    static int divisor(int x, int y) {
        if (y > x) {
            return divisor(y, x);
        }
        while (y != 0) {
            int remainder = x % y;
            x = y;
            y = remainder;
        }
        return x;
    }
}

