		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringBuilder isPrime1 = new StringBuilder();

		while(true){

			String[] line = br.readLine().split(" ");
			int LCD = Integer.parseInt(line[0]);
			int letter = Integer.parseInt(line[1]);

			if(LCD == 0 && letter == 0){
				break;
			}

			if(LCD <= letter){
				isPrime1.append(LCD + " " + letter + "\n");
			}else{
				isPrime1.append(letter + " " + LCD + "\n");
			}

		}

		System.out.print(isPrime1);

	}
}

