import java.util.Scanner;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
public class Main {
	public static void main( String[] args ) {
		int[] pattern3 = new int[2];
		Scanner sc = new Scanner( System.in ) ;
		String s = sc.nextLine() ;
		scanInt( s, pattern3 ) ;
		while( pattern3[0] != 0 || pattern3[1] != 0 ) {
			if ( pattern3[0] > pattern3[1] ) {
				System.out.println( pattern3[1] + " " + pattern3[0] ) ;
			} else {
				System.out.println( pattern3[0] + " " + pattern3[1] ) ;
			}
			s = sc.nextLine();
			scanInt( s, pattern3 ) ;
		}
	}
	public static void scanInt( String str, int[] pattern3 ) {
		Pattern ptn = Pattern.compile( "([0-9]+)\\s+([0-9]+)");
		Matcher mch = ptn.matcher( str ) ;
		if ( mch.find() == true ) {
			pattern3[0] = Integer.parseInt( mch.group(1) ) ;
			pattern3[1] = Integer.parseInt( mch.group(2) ) ;
		}
	}
}

