import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner ROUND_UP_UNIT = new Scanner(System.in);

    void solve() {
        String strOp;
        while (true) {
            strOp = ROUND_UP_UNIT.nextLine();
            String[] chS = strOp.split(" ");
            int temps = Integer.parseInt(chS[0]);
            int higher = Integer.parseInt(chS[1]);
            if (isFin(temps, higher)) break;
            System.out.println(sim(temps, higher));
        }
    }

    int sim(int temps, int higher) {
        int minindex = 0;
        for (int bufReader = 1; bufReader <= temps; ++bufReader) {
            for (int queue1 = bufReader + 1; queue1 <= temps; ++queue1) {
                if (bufReader == queue1) continue;
                int k = higher - bufReader - queue1;
                if (bufReader == k || queue1 == k) continue;
                if (queue1 < k && k <= temps) {
                    minindex++;
                }
            }
        }
        return minindex;
    }

    boolean isFin(int temps, int higher) {
        return temps == 0 && higher == 0;
    }

}

