			System.out.println(sum(n,tp));
		}					

	}
	public static int sum(int n,int tp){
		int count=0;
		for(int i=0;i<n;i++){
			for(int j=0;j<i;j++){
				for(int k=0;k<j;k++){
					if(tp-3==i+j+k){
						count=count+1;
					}
				}
			}
		}
		return count;
	}
}

