import java.util.Scanner;

public class Main{
	public static void main(String[] args){

		Scanner scan = new Scanner(System.in);

		//二つの行列の行と列を宣言
		int row = scan.nextInt();
		int TS = scan.nextInt();
		int T_array = scan.nextInt();

		//二つの行列(二次元配列)を宣言
		int[][] matrixA = new int[row][TS];
		int[][] label = new int[TS][T_array];
		long[][] time_sum = new long[row][T_array];

		//行列Aのためのループ
		for(int rowI = 0 ;rowI < row;rowI++){
			for(int columnRowI =0 ;columnRowI < TS ;columnRowI++){
				//行列Aの入力
				matrixA[rowI][columnRowI] = scan.nextInt();
			}
		}

		//行列Bのためのループ
		for(int columnRowI = 0 ;columnRowI < TS;columnRowI++){
			for(int columnI =0 ;columnI < T_array ;columnI++){
				//行列Bの入力
				label[columnRowI][columnI] = scan.nextInt();
			}
		}

		//行列Cの計算のためのループ
		for(int rowI = 0 ;rowI < row;rowI++){
			for(int columnRowI =0 ;columnRowI < T_array ;columnRowI++){
				for(int columnI =0 ;columnI < TS ;columnI++){

					//行列Cの入力
					time_sum[rowI][columnRowI]
							+= matrixA[rowI][columnI] * label[columnI][columnRowI];
				}
			}
		}
		for(int rowI = 0 ;rowI < row;rowI++){
			for(int columnI = 0 ;columnI < T_array ;columnI++){
				if(columnI+ 1 == T_array){
					System.out.println(time_sum[rowI][columnI]);
				}else if(columnI < T_array){
					System.out.print(time_sum[rowI][columnI] + " ");
				}
			}
		}
		scan.close();
	}
}

