public class Main{
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int parameter = Integer.parseInt(line[1]);
        int getX = Integer.parseInt(line[2]);
        int[][] eTime = new int[n][parameter];
        int[][] pointT = new int[parameter][getX];
        long[][] minusmove = new long[n][getX];

        for(int sigmaList = 0; sigmaList < n; sigmaList++){
            line = br.readLine().split(" ");
            for(int arrayAnswer = 0; arrayAnswer < parameter; arrayAnswer++){
                eTime[sigmaList][arrayAnswer] = Integer.parseInt(line[arrayAnswer]);
            }
        }

        for(int sigmaList = 0; sigmaList < parameter; sigmaList++){
            line = br.readLine().split(" ");
            for(int arrayAnswer = 0; arrayAnswer < getX; arrayAnswer++){
                pointT[sigmaList][arrayAnswer] = Integer.parseInt(line[arrayAnswer]);
            }
        }

        for(int sigmaList = 0; sigmaList < n; sigmaList++){
            for(int arrayAnswer = 0; arrayAnswer < getX; arrayAnswer++){
                for(int k = 0; k < parameter; k++)
                    minusmove[sigmaList][arrayAnswer] += eTime[sigmaList][k] * pointT[k][arrayAnswer];
            }
        }

        for(int sigmaList = 0; sigmaList < n; sigmaList++){
            for(int arrayAnswer = 0; arrayAnswer < getX; arrayAnswer++){
