import static java.math.BigInteger.*;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader startLen = new BufferedReader(new InputStreamReader(System.in));
		String Rmax;
		while(!"0".equals(Rmax = startLen.readLine())){
			System.out.println(sum(Rmax));
		}
	}

	private static int sum(String Rmax) {
		BigInteger C = new BigInteger(Rmax);
		if(C.compareTo(TEN) < 0){
			return Integer.parseInt(C.toString());
		}else{
			return Integer.parseInt(C.remainder(TEN).toString()) + sum(C.divide(TEN).toString());
		}
	}
}

