// Solution
public class Main {
  private static Scanner in;
  private static PrintWriter tmp;
  private static final String house = ""; // input file name

  /**
   * Interactive get next command
   */
  static int get(int ii) {
    tmp.println(ii + 1);
    tmp.flush();
    return ni();
  }

  static void solve() {
    int BIG_NUM = ni();
    int SStr = ni();

    int currentmin = (SStr / 2) - BIG_NUM;
    int notprime = BIG_NUM - currentmin ;

    if (SStr % 2 != 0 || currentmin < 0 || notprime < 0) {
      tmp.println("No");
    } else {
    	tmp.println("Yes");
    }
  }

  public static void main(String[] args) throws Exception {
    long count_1 = System.currentTimeMillis();
    in = house.isEmpty() ? new Scanner(System.in) : new Scanner(house);
    tmp = new PrintWriter(System.out);

    solve();
    tmp.flush();
    long tmpHigh = System.currentTimeMillis();
    tr(tmpHigh - count_1 + "ms");
  }

  private static int ni() {
    return Integer.parseInt(in.next());
  }

  private static long nl() {
    return Long.parseLong(in.next());
  }

  // Math Utils
  private static int pi(int newR, int pow) {
    int result = 1;

    while (pow > 0) {
      if (pow % 2 == 1) {
        result *= newR;
      }

      newR *= newR;
      pow /= 2;
    }

    return result;
  }

  private static int pim(int newR, int pow, int mod) {
    int result = 1;

    while (pow > 0) {
      if (pow % 2 == 1) {
        // keep collecting `odd` num in result
        result = (result * newR) % mod;
      }

      newR = (newR * newR) % mod;
      pow /= 2;
    }

    return result;
  }

  private static long pl(long newR, long pow) {
    long result = 1;

    while (pow > 0) {
      if (pow % 2 == 1) {
        result *= newR;
      }

      newR *= newR;
      pow /= 2;
    }

    return result;
  }

  private static long plm(long newR, long pow, long mod) {
    long result = 1;

    while (pow > 0) {
      if (pow % 2 == 1) {
        // keep collecting `odd` num in result
        result = (result * newR) % mod;
      }

      newR = (newR * newR) % mod;
      pow /= 2;
    }

    return result;
  }

  static void tr(Object... o) {
    if (!house.isEmpty())
      tmp.println(Arrays.deepToString(o));
  }
}

