import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int minDif;
    String[] totalTime;

    public void run() {
        // 入力情報取得
        Scanner sc = new Scanner(System.in);
        minDif = sc.nextInt();
        totalTime = new String[minDif];
        for (int i = 0; i < minDif; i++) {
            totalTime[i] = sc.next();
        }
        sc.close();

        // 解答処理
        solve();
    }

    private void solve() {
        totalTime = deduplication(totalTime);
        System.out.println(totalTime.length);
    }

    // 配列内の重複を排除
    private String[] deduplication(String[] totalTime) {
        Set<String> deduplicatedList = new LinkedHashSet<String>();
        for (int i = 0; i < totalTime.length; i++) {
            deduplicatedList.add(totalTime[i]);
        }
        String[] ret = deduplicatedList.toArray(new String[deduplicatedList.size()]);
        return ret;
    }
}

