        long END = printJudge.nextInt();
        long case_count = 0;
    for(long cloLarge = 1 ;cloLarge<=END;cloLarge++){
        for(long searches =1; searches <= cloLarge;searches++){
            for(long scanInt =1; scanInt <= searches;scanInt++){
                long huge = hogehoge(cloLarge,searches);
                huge = hogehoge(huge,scanInt);
                if(cloLarge == searches && searches==scanInt){
                    case_count += huge;
                }else if(cloLarge ==searches || searches ==scanInt){
