    public static long  hogehoge(long endTime , long b){
        long tmp;
        long sizeT =endTime;
        long skipUnprintable=b;
        while((tmp = sizeT % skipUnprintable) != 0){
            sizeT = skipUnprintable;
            skipUnprintable = tmp;
        }
        return skipUnprintable;
    }
}

