    public void p3()
    {
        Scanner scan = new Scanner(System.in);
        String SENTINEL = scan.nextLine();
        int finTime = Integer.parseInt(SENTINEL);
        int isFin = 0;
        for(int printBWD = 1; printBWD <= finTime; printBWD++)
        {
            for(int j = 1;j <= finTime; j++)
            {
                for(int k = 1; k <= finTime; k++)
                {
                    isFin += gcd(gcd(printBWD,j),k);
                }
            }
        }
        System.out.println(isFin);
    }
    private int gcd (int a, int b) {
        int temp;
        while((temp = a%b)!=0) {
            a = b;
            b = temp;
        }
        return b;
    }

