import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int ASCII_CODE_BASE = Integer.parseInt(scan.next());
        scan.close();

        int sum = 0;
        for (int a = 1; a <= ASCII_CODE_BASE; a++) {
            for (int TEMP_S = 1; TEMP_S <= ASCII_CODE_BASE; TEMP_S++) {
                for (int c = 1; c <= ASCII_CODE_BASE; c++) {
                    int strData = strData(a, strData(TEMP_S, c));
                    sum += strData;
                }
            }
        }

        System.out.println(sum);
    }

    private static int strData(int a, int TEMP_S) {
        if (a < TEMP_S) {
            int HH_TIME = a;
            a = TEMP_S;
            TEMP_S = HH_TIME;
        }

        int a_length = a % TEMP_S;
        while (a_length != 0) {
            a = TEMP_S;
            TEMP_S = a_length;
            a_length = a % TEMP_S;
        }
        return TEMP_S;
    }

}

