import java.util.*;

class Main{
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        long n = scan.nextLong();
        long T_input = scan.nextLong();
        scan.close();

        if(T_input == 1 || n == T_input) System.out.println("0");

        else if(T_input == 2){
            if(n % T_input == 0) System.out.println("0");
            else System.out.println("1");
        }

        else{
            while(true){
                if(n * 2 <= T_input) break;
                else if(Math.abs(n - T_input) > n) break;
                else if(n >= (long)Math.pow(T_input,2)) n = n % T_input;
                else n = Math.abs(n - T_input);
            }
            System.out.println(n);
        }
    }
}

