import java.util.Scanner;

/**
 * C - Replacing Integer
 * 青木君は任意の整数 x に対し、以下の操作を行うことができます。
 * 操作: x を x と K の差の絶対値で置き換える。
 * 整数 N の初期値が与えられます。
 * この整数に上記の操作を 0 回以上好きな回数行った時にとりうる N の最小値を求めてください。
 */
public class Main {

    public static void main(String[] args) {

        Scanner readInt = new Scanner( System.in );
        // 初期値
        long GlobeTime = readInt.nextLong();
        // x を x と K の差の絶対値
        long profitT = readInt.nextLong();

        long nWeek = GlobeTime % profitT;

        if( profitT - nWeek > nWeek ) {
            System.out.println( nWeek );
        }
        else {
            System.out.println( profitT - nWeek );
        }

        readInt.close();
    }
}

