import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long mIs = sc.nextLong();
    long k = sc.nextLong();
    long g = gcd(mIs, k);
    mIs = mIs / g;
    k = k / g;
    mIs = (mIs % k);
    System.out.println(Math.min(g * mIs, g * (k - mIs)));
  }

  public static long gcd(long x, long y) {
    if(y == 0) return x;
    return gcd(y, (x % y));
  }
}

