import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner _A = new Scanner(System.in);

	    long tall = execute(_A.nextLong(),_A.nextLong());
        System.out.println(tall);
    }

    public static long execute(long dataTime, long INTEREST_RATE){
        long plusTreated = dataTime % INTEREST_RATE;
        long minusTreated =Math.abs( plusTreated - INTEREST_RATE);
        long treated = Math.min(plusTreated,minusTreated);
        if(dataTime > treated) return execute(treated,INTEREST_RATE);
        return treated;
    }
}

