  public static void main(String[] args){
    Scanner ReadInt = new Scanner(System.in);
    long xcubic = ReadInt.nextLong();
    long checkPrime = ReadInt.nextLong();
    if(xcubic < checkPrime){
      long pow26 = checkPrime -xcubic;
      if(pow26 >= xcubic){
        System.out.println(xcubic); 
      }else{
        System.out.println(pow26); 
      }
    }else{
      long B = xcubic % checkPrime;
      long pow26 = checkPrime - B;
      if(pow26 >= B){
        System.out.println(B); 
      }else{
        System.out.println(pow26); 
      }
    }
    return;
  }
}

