import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int determinantB = sc.nextInt();

        Map<String, Integer> y_new = new TreeMap<>();
        int temp_time = 0;
        for (int i=0;i<determinantB;i++) {
            String S_n = sc.next();
            if (y_new.containsKey(S_n)) {
                int count = y_new.get(S_n);
                y_new.put(S_n, count + 1);
                if (temp_time <= count) temp_time = count + 1;
            } else {
                y_new.put(S_n, 1);
                if (temp_time == 0) temp_time = 1;
            }
        }

        for (String key : y_new.keySet()) {
            if (y_new.get(key) == temp_time) System.out.println(key);
        }

    }
}

