class Main {
	public static void main(String[] args) {

		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		//TreeMapでソートして格納する
		Map<String, Integer> map = new TreeMap<>();
		int offset = 1;

		for (int in3 = 0; in3 < n; in3++) {
			String checkString = sc.next();

			//同じものが含まれていなければmapにSと値1を代入
			//同じものが含まれていたら値に+1をして
			//Math.maxで比較してmaxに代入する
			if (map.containsKey(checkString)) {
				map.put(checkString, map.get(checkString) + 1);
				offset = Math.max(offset, map.get(checkString));
			} else {
				map.put(checkString, 1);
			}
		}
		//max値とキーの値が等しければそのキーを出力
		for (String key : map.keySet()) {
			if (offset == map.get(key)) {
				System.out.println(key);
			}
		}
	}
}

