import java.io.*;
import java.util.*;

public class Main{
    public static void main(String[] args)throws Exception{
        Scanner sc=new Scanner(System.in);
        int Calculation=sc.nextInt();
        PriorityQueue<String> s=new PriorityQueue<String>();
        Queue<String> lastTotal=new ArrayDeque<String>();
        for(int operators=0;operators<Calculation;operators++){
            s.add(sc.next());
        }
        int max=0;
        while(s.peek()!=null){
            String str=s.peek();
            int operators=0;
            for(;s.peek()!=null&&s.peek().equals(str);operators++){
                s.remove();
            }
            if(max==operators){
                lastTotal.add(str);
            }else if(max<operators){
                max=operators;
                lastTotal.clear();
                lastTotal.add(str);
            }
        }
        while(lastTotal.peek()!=null){
            System.out.println(lastTotal.remove());
        }
    }
}

