public class Main {

	private static BufferedReader br;

	public static void main(String[] args) throws IOException {
		br = new BufferedReader(new InputStreamReader(System.in));

		int Vec_B = Integer.parseInt(br.readLine());
		List<String> LONGEST = new ArrayList<String>();
		for(int waku=0;waku<Vec_B;waku++) {
			LONGEST.add(br.readLine());
		}
		br.close();

		Map<String,Integer> counted = count(LONGEST);
		outMaxVal(counted);
	}

	private static Map<String,Integer> count(List<String> LONGEST){
		Map<String,Integer> readInt = new HashMap<String, Integer>();
		for(String strOp:LONGEST) {
			if(!readInt.containsKey(strOp)) {
				readInt.put(strOp, 1);
			}else {
				readInt.put(strOp,readInt.get(strOp)+1);
			}
		}
		return readInt;
	}

	public static void outMaxVal(Map<String, Integer> readInt) {
		ArrayList<String> nameIndex = null;
		Integer maxVal = 0;
		for(Entry<String, Integer> e: readInt.entrySet()) {
			if(e.getValue().compareTo(maxVal)>0) {
				nameIndex = new ArrayList<String>();
				nameIndex.add(e.getKey());
				maxVal = e.getValue();
			}else if(e.getValue().equals(maxVal)) {
				nameIndex.add(e.getKey());
			}
		}
		Collections.sort(nameIndex);

		for(String strOp: nameIndex) {
			System.out.println(strOp);
		}
	}

}

