				isVisit.add(detectChar.get(i));
				strAryToIntAry.add(j);
				j =0;
			}
		}

		if(!flag) {
			strAryToIntAry.add(j);
		}

		int x = 0;
		int y = 0;
		List<Integer> s_length = new ArrayList<Integer>();
		List<String> result = new ArrayList<String>();

		for(int count:strAryToIntAry) {
			if(x==0) {
				s_length.add(strAryToIntAry.get(0));
				result.add(isVisit.get(0));
			}else {
				if(s_length.get(y)==count) {
					result.add(isVisit.get(x));
				}else if(s_length.get(y)<count) {
					s_length.clear();
					result.clear();
					s_length.add(strAryToIntAry.get(x));
					result.add(isVisit.get(x));
				}
			}
			x++;
		}

		for(String view:result) {
			System.out.println(view);
		}
		//		}
	}
}

