//		int num = Integer.parseInt(W.split(" ")[0]);

		Scanner inputNumber = new Scanner(System.in);
		int mx1 = inputNumber.nextInt();
		String processingTime = inputNumber.next();
		String score_avg = inputNumber.next();
		String runSchedule ="";

		for(int xcubic = 0;xcubic<mx1; xcubic++) {
			runSchedule += processingTime.charAt(xcubic);
			runSchedule += score_avg.charAt(xcubic);
		}




