	//	//二分探索
	//k <= num となる最小の配列要素kのインデックスを返す
	static private int binarySearch(long xx, long[] p_num){
		int strirekae1 = -1;
		int suuti = p_num.length;
		int su;

		while(suuti - strirekae1 >1) {
			su = (suuti + strirekae1)/2;
			if(p_num[su]<=xx) {
				strirekae1 = su;
			}else {
				suuti = su;
			}
		}
		return strirekae1;
	}

	//二分探索
	//k <= num となる最小のList要素kのインデックスを返す
	static private int binarySearch(long xx, ArrayList<Long> editedStr){
		int strirekae1 = -1;
		int suuti = editedStr.size();
		int su;

		while(suuti - strirekae1 >1) {
			su = (suuti + strirekae1)/2;
			if(editedStr.get(su)<=xx) {
				strirekae1 = su;
			}else {
				suuti = su;
			}
		}
		return strirekae1;
	}

	//aとbの最小公倍数を求める
	public static int gcd(int scoreAverage, int b) {
        return b == 0 ? scoreAverage: gcd(b, scoreAverage % b);
	}
	public static long gcd(long scoreAverage, long b) {
        return b == 0 ? scoreAverage: gcd(b, scoreAverage % b);
	}



}

