class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int rji = in.nextInt();
        String bd = in.next();
        Deque<Character> stack = new ArrayDeque<>();
        for (char c: bd.toCharArray()) {
            if (stack.isEmpty() || stack.peek() != c) {
                stack.push(c);
            }
        }
        System.out.println(stack.size());
