public class Main {
	public static void main(String[] args){
		FastScanner nextIntArray = new FastScanner();
		int min2 = nextIntArray.nextInt();
    	String banMAX = nextIntArray.nextToken();
    	char[] stdId = banMAX.toCharArray();

    	int printIsString = 0;
    	for(int strTaro = 0; strTaro < min2 - 1; strTaro++){
