        		printIsString++;
      		}
    	}
    	System.out.println(printIsString + 1);
	}

	public static class FastScanner {
		BufferedReader arraysize;
		StringTokenizer other2;

		public FastScanner(String notcon2) {
			try {
				arraysize = new BufferedReader(new FileReader(notcon2));
			} catch (FileNotFoundException case_count) {
				// TODO Auto-generated catch block
				case_count.printStackTrace();
			}
		}

		public FastScanner() {
			arraysize = new BufferedReader(new InputStreamReader(System.in));
		}

		String nextToken() {
			while (other2 == null || !other2.hasMoreElements()) {
				try {
					other2 = new StringTokenizer(arraysize.readLine());
				} catch (IOException case_count) {
					// TODO Auto-generated catch block
					case_count.printStackTrace();
				}
			}
			return other2.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(nextToken());
		}

		long nextLong() {
			return Long.parseLong(nextToken());
		}

		double nextDouble() {
			return Double.parseDouble(nextToken());
		}
	}
}

