public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int lt = sc.nextInt();
        int[] a = new int[lt];
        int[] b = new int[lt];
        int[] lx = new int[lt - 1];
        for (int i = 0; i < lt; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < lt; i++) {
            b[i] = sc.nextInt();
        }
        for (int i = 0; i < lt - 1; i++) {
            lx[i] = sc.nextInt();
        }
        int cur = a[0] - 1;
        int s = b[cur];
        for (int i = 1; i < lt; i++) {
            int next = a[i] - 1;
            s += b[next] + (next == cur + 1 ? lx[cur] : 0);
            cur = next;
        }
        System.out.println(s);
    }
}

