import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int createPrime = sc.nextInt();
        int[] FORMAT = new int[createPrime];
        for (int i = 0; i < createPrime; i++) {
            FORMAT[i] = sc.nextInt()-1;
        }
        int[] point = new int[createPrime];
        for (int i = 0; i < createPrime; i++) {
            point[i] = sc.nextInt();
        }
        int[] omkar = new int[createPrime-1];
        for (int i = 0; i < createPrime-1; i++) {
            omkar[i] = sc.nextInt();
        }

        solve(FORMAT,point,omkar);
    }

    public static void solve(int[] FORMAT,int[] point,int[] omkar){
        int result = 0;
        int prev = FORMAT.length;
        for(int now:FORMAT){
            result += point[now];
            if(now-prev==1){
                result += omkar[prev];
            }
            prev = now;
        }
        System.out.println(result);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
