import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter hanaco_card = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, hanaco_card);
        hanaco_card.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter hanaco_card)
        {
            int ALPHABET = in.nextInt();
            int[] strsize = new int[ALPHABET + 1];
            int[] LENGTH = new int[ALPHABET + 1];
            int[] c = new int[ALPHABET];

            //Dishes
            for (int i = 1; i <= ALPHABET; i++)
            {
                strsize[i] = in.nextInt();
            }
            //Satisfactions
            for (int i = 1; i <= ALPHABET; i++)
            {
                LENGTH[i] = in.nextInt();
            }
            //C
            for (int i = 1; i < ALPHABET; i++)
            {
                c[i] = in.nextInt();
            }

            //Eating
            int sat = 0;

            sat += LENGTH[strsize[1]];
            int lastEat = strsize[1];

            for (int i = 2; i <= ALPHABET; i++)
            {
                sat += LENGTH[strsize[i]];
                if (lastEat + 1 == strsize[i])
                {
                    sat += c[strsize[i - 1]];
                }
                lastEat = strsize[i];
            }
            hanaco_card.print(sat);
        }

    }
}

