import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {

	public static void main(String[] args) throws IOException {
		Main mainObj = new Main();
		mainObj.solve();
	}

	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		int dAry = fs.nextInt();
		int[] upperCase = fs.nextIntArr(dAry);
		int[] b = fs.nextIntArr(dAry);
		int[] c = fs.nextIntArr(dAry-1);

		int ans = 0;
		int before = -100;

		for(int i = 0; i < dAry; i++) {
			int mealNum = upperCase[i] - 1;
			ans += b[mealNum];
			if(before +1 == mealNum) {
				ans += c[before];
			}
			before = mealNum;
		}
		System.out.println(ans);
	}



	public class FastScanner {

		BufferedReader reader;
		private StringTokenizer st;

		public FastScanner() {
			st = null;
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (st == null || !st.hasMoreElements()) {
				st = new StringTokenizer(reader.readLine());
			}
			return st.nextToken();
		}

		public String nextLine() throws IOException {
			st = null;
			String readLine = null;
			readLine = reader.readLine();
			return readLine;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int dAry) throws NumberFormatException, IOException {
			int[] retArr = new int[dAry];
			for (int i = 0; i < dAry; i++) {
				retArr[i] = nextInt();
			}
			return retArr;
		}

		public long[] nextLongArr(int dAry) throws NumberFormatException, IOException {
			long[] retArr = new long[dAry];
			for (int i = 0; i < dAry; i++) {
				retArr[i] = nextLong();
			}
			return retArr;
		}

		public void close() throws IOException {
			reader.close();
		}
	}

}

