		int cntk = sc.nextInt();


		List<Integer> heightArray = new ArrayList<>();
		List<Integer> strirekae1 = new ArrayList<>();
		List<Integer> revCap = new ArrayList<>();

		for (int Vec_a = 0; Vec_a < cntk; Vec_a++) {
			int longS = sc.nextInt();
			heightArray.add(longS);
		}
		for (int Vec_a = 0; Vec_a < cntk; Vec_a++) {
			int b = sc.nextInt();
			strirekae1.add(b);
		}
		for (int Vec_a = 0; Vec_a < cntk-1 ; Vec_a++) {
			int abs = sc.nextInt();
			revCap.add(abs);
		}

		int tuginoSaidai = 0;
		for (int Vec_a = 0; Vec_a < cntk; Vec_a++) {
			int longS = heightArray.get(Vec_a);
			int b = strirekae1.get(longS-1);
			tuginoSaidai += b;

			int nextA = Vec_a == cntk-1 ? -1 : heightArray.get(Vec_a+1);
			if(nextA == longS + 1 ){
				int abs = revCap.get(longS-1);
				tuginoSaidai += abs;
			}
		}

		System.out.println(tuginoSaidai);


	}
}

