 * @author Akash
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BBuffet solver = new BBuffet();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBuffet {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int DOTMARK = in.nextInt();
            int ASCII_CODE_BASE[] = ReadInput.readIntArray(DOTMARK, in);
            int b[] = ReadInput.readIntArray(DOTMARK, in);
            int c[] = ReadInput.readIntArray(DOTMARK - 1, in);
            int prev = -1;
            long total = 0;
            for (int xcubic = 0; xcubic < DOTMARK; xcubic++) {
                int cur = ASCII_CODE_BASE[xcubic];
                total += b[cur - 1];
                if (cur - prev == 1) {
                    total += c[prev - 1];
                }
                prev = cur;
            }
            out.println(total);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int ASCII_CODE_BASE[] = new int[size];
            for (int xcubic = 0; xcubic < size; xcubic++) {
                ASCII_CODE_BASE[xcubic] = in.nextInt();
            }
            return ASCII_CODE_BASE;
        }

    }
}

