public class Main {

	public static void main(String[] args) {

		Scanner elapsed = new Scanner(System.in);
		final int Matrix = elapsed.nextInt();
		int[] bigInteger2 = new int[Matrix];		// 食べた料理の順番
		int[] satisfuction = new int[Matrix];		// 各料理の満足度
		int[] plusSatisfuction = new int[Matrix - 1];		// 連番のときに追加で得られる満足度
		int memory = Integer.MIN_VALUE;		// 直前に食べた料理の番号
		int answer = 0;			// 満足度の合計

		for(int i = 0; i < Matrix; i++) {
			bigInteger2[i] = elapsed.nextInt();
		}
		for(int i = 0; i < Matrix; i++) {
			satisfuction[i] = elapsed.nextInt();
		}
		for(int i = 0; i < Matrix - 1; i++) {
			plusSatisfuction[i] = elapsed.nextInt();
		}

		for(int i = 0; i < Matrix; i++) {
			answer += satisfuction[bigInteger2[i]-1];
			if(bigInteger2[i] - 1 == memory) {
				answer += plusSatisfuction[bigInteger2[i] - 2];
			}
			memory = bigInteger2[i];
		}

		System.out.println(answer);

	}
}

