		int b[] = new int[n];
		int B1[] = new int[n-1];
		int sum = 0;
		for(int i = 0; i < n; i++) {
			ms[i] = sc.nextInt();
		}
		for(int i = 0; i < n; i++) {
			b[i] = sc.nextInt();
		}
		for(int i = 0; i < n-1; i++) {
			B1[i] = sc.nextInt();
		}

		for(int i = 0; i < n; i++) {
			if(pnum != 0) {
				if((pnum+1) == ms[i])
					sum += B1[pnum-1];
			}
			int num = ms[i];
			sum += b[num-1];
			pnum = num;
			//System.out.println(sum);
		}
		System.out.println(sum);
	}


}

import java.util.Scanner;

class Solver {
    void solve(Scanner tmp1) {
        int S3 = tmp1.nextInt();
        int[] printProcess = new int[S3];
        int[] gi = new int[S3];
        int[] xclubic = new int[S3 - 1];
        for (int i = 0; i < printProcess.length; i++) {
            printProcess[i] = tmp1.nextInt() - 1;
        }
        for (int i = 0; i < gi.length; i++) {
            gi[i] = tmp1.nextInt();
        }
        for (int i = 0; i < xclubic.length; i++) {
            xclubic[i] = tmp1.nextInt();
        }
        int sum = gi[printProcess[0]];
        for (int i = 1; i < S3; i++) {
            int intS = printProcess[i - 1];
            int next = printProcess[i];
            if (intS + 1 == next) sum += xclubic[intS];
            sum += gi[next];
        }
        System.out.println(sum);
    }
}

class Main {
    public static void main(String... args) {
        Scanner in = new Scanner(System.in);

        new Solver().solve(in);

        in.close();
    }
}

