public class Main {
	public static void main(String[] args) {
		Scanner gc1 = new Scanner(System.in);
		int x_list = Integer.parseInt(gc1.nextLine());
		int[] buffets = new int[x_list];
		int[] dx = new int[x_list];
		int[] isBiggerA = new int[x_list - 1];
		for(int weatherList = 0; weatherList < x_list; weatherList++) {
			buffets[weatherList] = Integer.parseInt(gc1.next());
		}
		for(int weatherList = 0; weatherList < x_list; weatherList++) {
			dx[weatherList] = Integer.parseInt(gc1.next());
		}
		for(int weatherList = 0; weatherList < x_list - 1; weatherList++) {
			isBiggerA[weatherList] = Integer.parseInt(gc1.next());
		}
		System.out.println(new Main().buffet(x_list, buffets, dx, isBiggerA));
		gc1.close();
	}

	public int buffet(int x_list, int[] buffets, int[] dx, int[] isBiggerA) {
		int prev_buffet = -1;
		int targetChar = 0;
		for(int weatherList = 0; weatherList < x_list; weatherList++) {
			targetChar += dx[buffets[weatherList] - 1];
			if(prev_buffet + 1 == buffets[weatherList]) {
				targetChar += isBiggerA[prev_buffet - 1];
			}
			prev_buffet = buffets[weatherList];
		}
		return targetChar;
	}
}

