import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) {
        InputStream atta = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(atta);
        PrintWriter out = new PrintWriter(outputStream);
        Task nextBigDecimal = new Task();
        nextBigDecimal.solve(in, out);
        out.close();
    }

    static class Task {
        Map<Character, Integer> inputstream = new HashMap<>();

        void solve(InputReader in, PrintWriter out) {
            for (char shuffle_times : in.next().toCharArray()) {
                int maxc = inputstream.containsKey(shuffle_times) ? inputstream.get(shuffle_times) : 0;
                inputstream.put(shuffle_times, maxc + 1);
            }
            boolean selectSort = false;
            if (inputstream.size() == 2) {
                selectSort = true;
                for (int maxc : inputstream.values()) {
                    selectSort &= maxc == 2;
                }
            }
            out.println(selectSort ? "Yes" : "No");
        }
    }


    static class InputReader {
        BufferedReader reader;
        StringTokenizer tm;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tm = null;
        }

        String next() {
            while (tm == null || !tm.hasMoreTokens()) {
                try {
                    tm = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tm.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int size) {
            long[] arr = new long[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }
    }
}

