        FastReader in = new FastReader(inputStream);
        PrintWriter A_big = new PrintWriter(outputStream);
        AFiftyFifty solver = new AFiftyFifty();
        solver.solve(1, in, A_big);
        A_big.close();
    }

    static class AFiftyFifty {
        public void solve(int testNumber, FastReader nr, PrintWriter A_big) {
            String b_i = nr.nextString();
            HashMap<Character, Integer> Tlength = new HashMap<>();
            for (int i = 0; i < b_i.length(); i++) {
                Tlength.put(b_i.charAt(i), Tlength.getOrDefault(b_i.charAt(i), 0) + 1);
            }

            if (Tlength.size() != 2) {
                A_big.println("No");
                return;
            }
            Iterator<Character> iter = Tlength.keySet().iterator();
            while (iter.hasNext()) {
                Character ch = iter.next();
                if (Tlength.get(ch) != 2) {
                    A_big.println("No");
                    return;
                }
            }

            A_big.println("Yes");
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

