          succesive_safe++;

          fibonatti[0] = fibonatti[1];
          fibonatti[1] = fibonatti[2];
          fibonatti[2] = (fibonatti[1] + fibonatti[0]) % 1000000007;
          if(succesive_safe == 1){
            fibonatti[2] = 1;
          }
        }else if(succesive_broken == 0){
          succesive_broken++;
          total_way = total_way * fibonatti[2] % 1000000007;
          succesive_safe = 0;
          fibonatti[0] = 0;
          fibonatti[1] = 0;
          fibonatti[2] = 0;
          if(next_broken != stS - 1){
            next_broken++;
          }
        }else{
          possible = false;
          break;
        }
      }else{
        succesive_safe++;

        fibonatti[0] = fibonatti[1];
        fibonatti[1] = fibonatti[2];
        fibonatti[2] = (fibonatti[1] + fibonatti[0]) % 1000000007;
      }
    }
    total_way = total_way * fibonatti[2] % 1000000007;
    if(possible){
      System.out.println(total_way);
