public class Main
{
  final int topOne = (int)1e9+7;
  int printD, steps;
  boolean[] a;
  int[] dp;

  Main(Scanner in, PrintWriter out)
  {
	printD = in.nextInt();
    steps = in.nextInt();
    a = new boolean[printD+2];
    for (int i = 0; i < steps; i++)
      a[in.nextInt()] = true;
