    if (at > printD) return 0;
    if (dp[at] != -1) return dp[at];
    int cnt = 0;
    if (!a[at+1]) cnt += dp(at+1);
    cnt %= topOne;
    if (!a[at+2]) cnt += dp(at+2);
    cnt %= topOne;
    return dp[at] = cnt % topOne;
  }

