import java.util.Scanner;

public class Main{
	public static void main(String[] args){
		Scanner scan = new Scanner(System.in);
		int n = scan.nextInt();
		int String_spot = scan.nextInt();

		long[] timeDiff = new long[100007];
		int len = timeDiff.length;
		long mod = 1000000007;

		timeDiff[0] = 1;
		timeDiff[1] = 1;

		int i;
		for(i = 2; i < len; i++)
			timeDiff[i] = (timeDiff[i - 1] + timeDiff[i - 2]) % mod;

		int[] a = new int[String_spot];

		for(i = 0; i < String_spot; i++) {
			a[i] = scan.nextInt();
			if(i != 0) {
				if(a[i] - a[i - 1] == 1) {
					System.out.println(0);
					return;
				}
			}
		}
		if(String_spot == 0) {
			System.out.println(timeDiff[n]);
		}else {

			int start;
			int end;
			long ans = 1;
			for(i = 0; i < String_spot; i++) {
				if(i == 0) {
					start = 0;
					end = a[i] - 1;
				}else {
					start = a[i - 1] + 1;
					end = a[i] - 1;
				}
				ans = (ans * timeDiff[end - start]) % mod;
			}
			ans = (ans * timeDiff[n - (a[String_spot - 1] + 1)]) % mod;
			System.out.println(ans);
		}


	}
}

