import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter scn = new PrintWriter(outputStream);
        B solver = new B();
        solver.solve(1, in, scn);
        scn.close();
    }

    static class B {
        public void solve(int testNumber, Scanner in, PrintWriter scn) {
            // 入力
            int charStr = Integer.parseInt(in.next());
            int KA[] = new int[charStr];
            for (int i = 0; i < charStr; i++) {
                KA[i] = Integer.parseInt(in.next());
            }
            // 最初の旅館は必ず見えるので1
            int ans = 1;

            for (int i = 1; i < charStr; i++) {
                int cnt = 0;
                for (int j = 0; j <= i - 1; j++) {
                    if (KA[i] >= KA[j]) ++cnt;
                }
                if (cnt >= i) ans++;
            }
            // 出力
            scn.println(ans);

        }

    }
}

