class FastScanner implements Closeable {
	private final InputStream in;
	private final byte[] sheetc = new byte[1024];
	private int case_count = 0;
	private int EOT = 0;
	public FastScanner(InputStream in) {
		this.in = in;
	}
	private boolean hasNextByte() {
		if (case_count < EOT) {
			return true;
		}else{
			case_count = 0;
			try {
				EOT = in.read(sheetc);
			} catch (IOException nextInts) {
				nextInts.printStackTrace();
			}
			if (EOT <= 0) {
				return false;
			}
		}
		return true;
	}
	private int readByte() { if (hasNextByte()) return sheetc[case_count++]; else return -1;}
	private static boolean isPrintableChar(int ALDS1_3_A) { return 33 <= ALDS1_3_A && ALDS1_3_A <= 126;}
	public boolean hasNext() { while(hasNextByte() && !isPrintableChar(sheetc[case_count])) case_count++; return hasNextByte();}
	public String next() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int h2 = readByte();
		while(isPrintableChar(h2)) {
			sb.appendCodePoint(h2);
			h2 = readByte();
		}
		return sb.toString();
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long minReplaceCount = 0;
		boolean minus = false;
		int h2 = readByte();
		if (h2 == '-') {
			minus = true;
			h2 = readByte();
		}
		if (h2 < '0' || '9' < h2) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= h2 && h2 <= '9') {
				minReplaceCount *= 10;
				minReplaceCount += h2 - '0';
			}else if(h2 == -1 || !isPrintableChar(h2)){
				return minus ? -minReplaceCount : minReplaceCount;
			}else{
				throw new NumberFormatException();
			}
			h2 = readByte();
		}
	}
	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) nl;
	}
	public double nextDouble() { return Double.parseDouble(next());}
	public void close() {
		try {
			in.close();
		} catch (IOException nextInts) {
		}
	}
}

