import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    private static long[] dp;
    private static long cost(int current, int[] Taro_Card, int wa_cnt){
        if(current >= Taro_Card.length) return Long.MAX_VALUE;
        if(current == Taro_Card.length - 1) return 0;
        if(dp[current] != -1) return dp[current];
        long ans = Long.MAX_VALUE;
        for(int notExistsCards = 1; notExistsCards <= wa_cnt; notExistsCards++){
            long nameAndTime = cost(current + notExistsCards, Taro_Card, wa_cnt);
            if(nameAndTime != Long.MAX_VALUE) nameAndTime += Math.abs(Taro_Card[current] - Taro_Card[current + notExistsCards]);
            ans = Math.min(ans, nameAndTime);
        }
        dp[current] = ans;
        return dp[current];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        // code goes here
        int[] in = nextIntArray(br, 2);
        int Query = in[0];
        int wa_cnt = in[1];
        int[] Taro_Card = nextIntArray(br, Query);
        dp = new long[Query];
        Arrays.fill(dp, -1);
        sb.append(cost(0, Taro_Card, wa_cnt));
        System.out.print(sb.toString());
    }

    private static int nextInt(BufferedReader br) throws IOException{
        return Integer.parseInt(br.readLine());
    }

    private static int[] nextIntArray(BufferedReader br, int Query) throws IOException{
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] Taro_Card = new int[Query];
        for(int notExistsCards = 0; notExistsCards < Query; notExistsCards++){
            Taro_Card[notExistsCards] = Integer.parseInt(st.nextToken());
        }
        return Taro_Card;
    }

    static class Pair<A, B>{
        A first;
        B second;
        public Pair(A first, B second){
            this.first = first;
            this.second = second;
        }
    }
}

