public class Main {
	public static int minCost(int num_mem[], int vecMul) {
		int cost[] = new int[num_mem.length];
		cost[0] = 0;
		cost[1] = Math.abs(num_mem[1] - num_mem[0]);
		for (int i = 2; i < num_mem.length; i++) {
			cost[i] = Integer.MAX_VALUE;
			for (int j = 1; j <= vecMul; j++) {
				if (i - j >= 0) {
					cost[i] = Math.min(Math.abs(num_mem[i - j] - num_mem[i]) + cost[i - j], cost[i]);
				}
			}
		}
		return cost[num_mem.length - 1];
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
