class Main
{
	static Integer dp[];

	static int minimumJumps(int Tall[], int i, int QueueImpl)
	{
		if(i==0)
			return 0;

		if(dp[i]!=null)
			return dp[i];

		int min=Integer.MAX_VALUE;
		int st=Math.max(i-QueueImpl, 0);

		for(int j=st;j<i;j++)
		{
			if(dp[j]==null)
				min = Math.min(min, minimumJumps(Tall, j, QueueImpl)+Math.abs(Tall[i]-Tall[j]));
			else
				min = Math.min(min, dp[j]+Math.abs(Tall[i]-Tall[j]));
		}
		return dp[i]=min;
	}

	public static void main(String[] args)
	{
		Scanner scan=new Scanner(System.in);
		int eTime=scan.nextInt();
		int QueueImpl=scan.nextInt();
		int Tall[]=new int[eTime];
		for(int i=0;i<eTime;i++)
			Tall[i]=scan.nextInt();

		dp=new Integer[eTime];

		int createMatrix = minimumJumps(Tall, Tall.length-1, QueueImpl);
		System.out.println(createMatrix);
	}
}

