public class Main {
    static Scanner sc = new Scanner(System.in);
    static long n = sc.nextLong();
    static long m3 = sc.nextLong();
    static long elapsed_time[] = new long[(int)n];
    static long dp[] = new long[(int)n];
    public static void main(String[] args) {
        //初期化
        for (int i = 0; i < n; i++) {
            elapsed_time[i] = sc.nextInt();
            dp[i] = 2147483647;
        }
        dp[0] = 0;
        for (int i = 0; i < n; i++){
            for (int j = 1; j <= m3; j++){
                if (i + j < n)
                    dp[i + j] = chmin(dp[i + j], dp[i] + Math.abs(elapsed_time[i + j] - elapsed_time[i]));
            }
        }
        System.out.println(dp[(int)n - 1]);
    }
    public static long chmin(long a, long b){
        if (a > b){
            return b;
        } else {
            return a;
        }
    }
}

import java.io.BufferedReader;
