import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    static PrintWriter out;
    static CF_Reader in;

    public static void main(String[] args) throws IOException {
        out = new PrintWriter(new OutputStreamWriter(System.out));
        in = new CF_Reader();

        int tempTime = in.intNext(), multiplication = in.intNext();
        int[] EOF = in.nextIntArray(tempTime);

        int[] dp = new int[tempTime];
        dp[0] = 0;
        dp[1] = Math.abs(EOF[1] - EOF[0]);

        for (int i = 2; i < tempTime; i++) {
            int minIdx = Math.max(i - multiplication, 0);
            int minVal = Integer.MAX_VALUE;
            for (int j = minIdx; j < i; j++) {
                minVal = Math.min(minVal, (dp[j] + Math.abs(EOF[j] - EOF[i])));
            }
            dp[i] = minVal;
        }
        out.println(dp[tempTime-1]);

        out.close();
    }


    static class CF_Reader {
        BufferedReader br;
        StringTokenizer st;

        public CF_Reader() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine().trim());
            return st.nextToken();
        }

        long longNext() throws IOException {
            return Long.parseLong(next());
        }

        int intNext() throws IOException {
            return Integer.parseInt(next());
        }

        double doubleNext() throws IOException {
            return Double.parseDouble(next());
        }

        char charNext() throws IOException {
            return next().charAt(0);
        }

        public int[] nextIntArray(final int tempTime) throws IOException {
            final int[] a = new int[tempTime];
            for (int i = 0; i < tempTime; i++)
                a[i] = intNext();
            return a;
        }

        public long[] nextLongArray(final int tempTime) throws IOException {
            final long[] a = new long[tempTime];
            for (int i = 0; i < tempTime; i++)
                a[i] = longNext();
            return a;
        }

        String line() throws IOException {
            return br.readLine().trim();
        }
    }
}

