        Scanner input = new Scanner(System.in);
        int tuple = input.nextInt();
        int time = input.nextInt();
        int[] unit = new int[tuple];
        int[] dp = new int[tuple];
        for(int i=0;i<tuple;++i){
            unit[i]=input.nextInt();
        }
        if(tuple==0 || tuple==1)
            System.out.println("0");
        else {
            dp[1]=Math.abs(unit[1]-unit[0]);
            for (int i = 2; i < tuple; ++i) {
                int ans = Integer.MAX_VALUE;
                int j = i-time;
                if(j<0)j=0;
                for(int l=j;l<i;++l){
                    int val = dp[l]+Math.abs(unit[i]-unit[l]);
                    ans = Math.min(ans,val);
                }
                dp[i]=ans;
            }
        }
        System.out.println(dp[tuple-1]);

    }
}

