			sum += (s % 10);
			s /= 10;
		}
		return sum;
	}
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt(), calcT = sc.nextInt(), B = sc.nextInt();
		int[] keta = new int[N + 1];
		for(int i = 0; i < N + 1; i++) keta[i] = keta(i);
		int sum = 0;
