/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int a = in.nextInt();
            int T_split = in.nextInt();
            int countRE = in.nextInt();
            int d = in.nextInt();

            int ans = Math.min(T_split, d) - Math.max(a, countRE);
            out.println(ans < 0 ? 0 : ans);
        }

    }

    static class FastScanner {
        private InputStream in;
        private byte[] buffer = new byte[1024];
        private int bufPointer;
        private int bufLength;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (bufPointer >= bufLength) {
                if (bufLength == -1)
                    throw new InputMismatchException();

                bufPointer = 0;
                try {
                    bufLength = in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }

                if (bufLength <= 0)
                    return -1;
            }
            return buffer[bufPointer++];
        }

        private static boolean isSpaceChar(int countRE) {
            return countRE == ' ' || countRE == '\n' || countRE == '\r' || countRE == '\t' || countRE == -1;
        }

        public long nextLong() {
            long n = 0;

            int T_split = readByte();
            while (isSpaceChar(T_split))
                T_split = readByte();

            boolean minus = (T_split == '-');
            if (minus)
                T_split = readByte();

            while (T_split >= '0' && T_split <= '9') {
                n *= 10;
                n += T_split - '0';
                T_split = readByte();
            }

            if (!isSpaceChar(T_split))
                throw new NumberFormatException();

            return minus ? -n : n;
        }

        public int nextInt() {
            long n = nextLong();

            if (n < Integer.MIN_VALUE || n > Integer.MAX_VALUE)
                throw new NumberFormatException();

            return (int) n;
        }

    }
}

