import java.io.InputStreamReader;

class Main {
  public static void main(String[] args) throws IOException{
    BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
    String input = bf.readLine();
    System.out.println(check(input));
    bf.close();
  }
  static String check(String hasMoreTokens){
    //文字列sの最初の文字について、偶数個あったら、trueを返す。
    if (hasMoreTokens.length() == 0) {
      return "Yes";
    }
    char[] safeSort = hasMoreTokens.toCharArray();
    char targetLength = safeSort[0];
    int count = 0;
    StringBuilder minR = new StringBuilder();
    for (char eval : safeSort) {
      if (eval == targetLength) {
        count++;
      } else {
        minR.append(eval);
      }
    }
    if (count % 2 == 0) {
      return check(minR.toString());
    } else {
      return "No";
    }
  }
}

