public class Main {
  public static void main(String[] args) {
    Scanner dfs = new Scanner(System.in);
    String w = dfs.nextLine();
    boolean makePrimeList = solve(w);
    if(makePrimeList)
      System.out.println("Yes");
    else
      System.out.println("No");
  }

  public static boolean solve(String w){
    boolean makePrimeList = true;
    int hights = 0;
    for(int i = 0; i < w.length() ; i++){
      for(int j = 0; j < w.length() ; j++){
        if(w.charAt(i) == w.charAt(j))
          hights += 1;
      }
      if(hights % 2 != 0 ){
        makePrimeList = false;
        break;
      }
    }
    return makePrimeList;
  }
}

